"""Build the seven-page MovieLens site with the approved dashboard design."""
from pathlib import Path
ROOT=Path(__file__).resolve().parent
PAGES={
'index':('Home','''<section class="hero"><div><p class="eyebrow">NEXT FRAME / THE DISCOVERY LAB</p><h1>A little less searching.<br>A lot more watching.</h1><p>Find your next film. Explore the audience patterns behind it.</p><div class="actions"><a class="button bright" href="discover.html">Explore the catalogue</a><a class="button glass" href="recommendations.html">Find my next film</a></div><div class="hero-tags"><span>MovieLens · through October 2023</span><span>Real model evaluation</span><span>No account needed</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><div class="center-mark">N<span>F</span></div><span class="art-label">PATTERNS INTO PICTURES</span></div></section><div id="stats" class="stats"></div><section class="split"><div class="panel"><p class="eyebrow">EXPLORE THE EVIDENCE</p><h2>Every recommendation<br>starts with a pattern.</h2><p>See how audiences rate films, which genres appear in the catalogue, and how the model learns. Every graph connects to recorded MovieLens data.</p><a class="text-link" href="explorer.html">Open the Data Explorer</a></div><div id="home-chart" class="panel"></div></section><div class="section-title"><div><p class="eyebrow">START EXPLORING</p><h2>From the historical catalogue</h2></div><a class="button secondary" href="discover.html">Browse all films</a></div><div id="featured" class="cards"></div>'''),
'discover':('Discover','''<div class="page-heading"><p class="eyebrow">YOUR NEXT DISCOVERY</p><h1>Find your kind of film.</h1><p>Search the trained catalogue by title, genre and release year.</p></div><section class="panel filters"><label>Search films<input id="search" type="search" placeholder="Try Barbie, Oppenheimer, or The Matrix"></label><label>Genre<select id="genre"><option>All genres</option></select></label><label>Release year<select id="year"><option>All years</option></select></label><label>Model support<select id="support"><option value="all">All trained films</option><option value="supported">At least 20 training ratings</option></select></label><label>Sort<select id="sort"><option value="count">Most training ratings</option><option value="year">Newest release year</option><option value="title">Title A–Z</option></select></label><button id="reset" class="secondary">Reset filters</button></section><p class="note">The dataset ends October 12, 2023. Catalogue coverage is limited to movies observed in our training sample; not every 2023 release is included. Counts and averages below use training ratings only.</p><div class="section-title"><p id="result-count" role="status"></p><div class="actions"><button id="previous" class="secondary">Previous</button><span id="page-number"></span><button id="next" class="secondary">Next</button></div></div><div id="movies" class="cards"></div>'''),
'recommendations':('My Recommendations','''<div class="page-heading"><p class="eyebrow">MADE FOR YOUR TASTE</p><h1>Tell us what you watch.</h1><p>Rate a few familiar films to discover five more.</p></div><section class="panel"><h2>Your film profile</h2><p>Rate at least three supported films from 0.5 to 5 stars. Include something you liked and something you disliked: above 3 stars signals a like, below 3 a dislike. Your ratings stay in this browser tab until cleared.</p><label>Find a film you know<input id="rec-search" type="search" placeholder="Search the supported catalogue"></label><div id="rate-movies" class="rating-grid"></div><section class="preference-panel"><p class="eyebrow">SET THE MOOD</p><h3>What are you in the mood for?</h3><p>Blend your taste with genre similarities, or narrow your shortlist.</p><div class="preference-grid"><label>Recommendation style<select id="rec-mode"><option value="balanced">For your taste</option><option value="collaborative">Audience patterns</option><option value="genre">More like my genres</option></select></label><label>Include genre<select id="rec-genre"><option value="">Any genre</option></select></label><label>Exclude genre<select id="rec-exclude"><option value="">No exclusions</option></select></label><label>Animation<select id="rec-animation"><option value="any">Any film</option><option value="only">Animation only</option><option value="exclude">Exclude animation</option></select></label><label>Released from<input id="rec-from" type="number" min="1874" max="2023" placeholder="Any year"></label><label>Released through<input id="rec-to" type="number" min="1874" max="2023" placeholder="2023"></label></div><button id="rec-reset" class="secondary">Reset preferences</button><p class="note">Genre filters match MovieLens labels. Franchise, director and studio filters need verified additional metadata and are not available yet.</p></section><div id="my-ratings" class="chips"></div><div class="actions"><button id="recommend" class="primary">Find my recommendations</button><button id="clear-ratings" class="secondary">Clear my ratings</button></div><p id="rec-status" role="status"></p><details><summary>Explore a dataset user instead</summary><p>Three reproducible examples from our sampled MovieLens users.</p><label>Example user<select id="example-user"></select></label><button id="example-go" class="secondary">Show example recommendations</button></details></section><section id="recommendation-section" hidden><div class="section-title"><div><p class="eyebrow">YOUR SHORTLIST</p><h2>Five films to consider</h2><p id="recommendation-label"></p></div></div><div id="recommendation-cards" class="cards"></div><p class="note">Rated films are excluded. For your new profile, ordering combines collaborative movie similarities, matrix-factorization preferences and genre similarity. Filters may leave fewer than five eligible films. Stars on visitor cards are observed training audience averages, not predicted personal ratings or match percentages. Dataset examples retain estimated stars and their separately evaluated ranking rule. New-viewer recommendation quality has not been evaluated on held-out users.</p></section>'''),
'movie':('Movie Details','''<a class="text-link" href="discover.html">Back to Discover</a><section id="movie-detail" class="panel detail"></section><div class="split"><section class="panel" id="movie-comparison"></section><section class="panel"><p class="eyebrow">READ THE SCORE CORRECTLY</p><h2>Audience averages.<br>Personal estimates.</h2><p>A movie's average describes observed training ratings. A personalized estimate comes from the viewer and movie factors. Neither guarantees that you will enjoy the film.</p><p>MovieLens supplies ratings and identifiers. Posters load from an external image service using the source IMDb mapping. When artwork is unavailable, a typographic cover takes its place.</p><a class="text-link" href="performance.html">See model evaluation</a></section></div><div class="section-title"><h2>Explore a shared genre</h2></div><div id="related" class="cards"></div>'''),
'explorer':('Data Explorer','''<div class="page-heading"><p class="eyebrow">THE NUMBERS BEHIND THE FILMS</p><h1>Make the patterns visible.</h1><p>Explore audience feedback, genre coverage and the shape of the catalogue.</p></div><div id="stats" class="stats"></div><div class="chart-grid"><section class="panel" id="distribution"></section><section class="panel" id="genres"></section><section class="panel wide" id="timeline"></section><section class="panel wide" id="releases"></section><section class="panel wide" id="heatmap"></section><section class="panel wide" id="scatter"></section></div><section class="panel"><h2>What the charts cannot tell us</h2><p>Rating counts are not ticket sales, streaming views or current popularity. Genres overlap, and the selected users are only a sample of MovieLens. Release years are extracted from the source titles. No chart establishes that a genre causes better ratings.</p><p id="coverage-note" class="note"></p></section>'''),
'performance':('Model Performance','''<div class="page-heading"><p class="eyebrow">MEASURE BEFORE YOU CLAIM</p><h1>How good are the recommendations?</h1><p>A held-out test set and two kinds of evaluation keep us honest.</p></div><section class="panel"><p>Rating errors use the 0.5–5 star scale. Lower RMSE and MAE are better.</p><div id="model-stats" class="stats"></div></section><div class="chart-grid"><section class="panel" id="error-chart"></section><section class="panel" id="rank-chart"></section><section class="panel" id="recall-chart"></section><section class="panel" id="ndcg-chart"></section><section class="panel wide" id="ranking-selection"></section><section class="panel wide" id="training-chart"></section></div><section class="panel"><h2>Better ranking, with a popularity trade-off.</h2><p>The original factor model slightly improves star-rating error but gives weak top-five results. The updated ranker combines its personal estimate with training rating counts. Validation selected a support weight of 1.6. It improves all three ranking metrics over the original model and movie-average baseline. Compared with the most-rated baseline, precision and NDCG improve modestly, while recall is slightly lower. These are descriptive results, not a statistical significance claim.</p><div class="steps"><article><b>01 / Prepare</b><p>Sample 5,000 users with seed 42. Split each user's history chronologically into approximately 80% training, 10% validation and 10% test ratings.</p></article><article><b>02 / Select</b><p>Train four factor/regularization configurations. Select factor settings and early stopping using validation RMSE. Then select the ranking weight using NDCG@5 on 500 validation users.</p></article><article><b>03 / Evaluate</b><p>Freeze the ranking weight before evaluating the same historical test cohort of 200 users. This is a comparison on an already-used test set, not a fresh untouched benchmark.</p></article></div><p id="fallback-note" class="note"></p><p class="note">The rating baseline uses user/movie biases. Ranking comparisons include both a Bayesian movie average and a most-rated baseline. The support bonus favors popular titles and may reduce novelty. Displayed star estimates are unchanged; they are distinct from the score used to order recommendations. Ranking relevance is a held-out rating of at least four stars; unobserved relevance is unknown. Per-user chronological splits are not a globally prospective backtest. These results evaluate existing users, not the new visitor hybrid. Visitor recommendations combine training-only item similarities and a smaller matrix-factorization preference signal; their quality has not yet received a held-out evaluation.</p></section>'''),
'about':('About','''<div class="page-heading"><p class="eyebrow">ABOUT THIS PROJECT</p><h1>Curiosity, with evidence.</h1><p>A movie recommendation and data-visualization project for the B.Y.T.E Data Science internship.</p></div><div class="split"><section class="panel"><p class="eyebrow">THE BUILDER</p><h2>Jarrod Frank Tamargo</h2><p>This project explores how collaborative filtering turns audience ratings into recommendations—and how clear visualizations explain the evidence and limitations.</p><a class="text-link" href="https://github.com/jarrodfranktamargocics-ui">GitHub profile</a></section><section class="panel"><p class="eyebrow">THE APPROACH</p><h2>Learn shared preferences.</h2><p>Biased matrix factorization learns a numerical profile for every sampled user and trained movie. A new viewer's ratings fit a temporary profile against the fixed movie factors. Visitor ordering also uses item similarities learned from training audience ratings, so liked and disliked films directly affect the shortlist.</p><p>Missing ratings are unknown, not zero-star reviews. Recommendations exclude known rated films and require at least 20 training ratings per candidate. A validation-selected support bonus balances the personal estimate with how widely a movie was rated; it can favor familiar popular titles.</p></section></div><section class="panel"><h2>Sources &amp; provenance</h2><p><a href="https://grouplens.org/datasets/movielens/32m/">MovieLens 32M — GroupLens</a>. Original data contains 32,000,204 ratings and 87,585 movies. Its ratings end October 12, 2023. Our catalogue and results describe a smaller reproducible sample.</p><p>F. Maxwell Harper and Joseph A. Konstan, The MovieLens Datasets: History and Context, ACM TiiS, 2015.</p><p id="provenance"></p><a class="text-link" href="DATASET_LICENSE.txt">Dataset attribution and terms</a><p class="note">Educational, noncommercial demonstration. No live streaming availability, ticket prices or 2026 catalogue coverage is claimed. A few source entries may be series or other screen titles.</p></section><section class="panel"><h2>Your choices stay local</h2><p>No sign-in is needed. Ratings stay in this tab's session storage and can be erased using Clear my ratings. There is no analytics or tracking code. Poster images load from MetaHub, which receives ordinary image requests; your entered ratings are not sent to that service.</p></section>''')}
for slug,(title,body) in PAGES.items():
    nav=''.join(f'<a href="{key}.html"'+(' aria-current="page"' if key==slug else '')+f'>{label}</a>' for key,(label,_) in PAGES.items() if key!='movie')
    (ROOT/'web'/f'{slug}.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Next Frame</title><meta name="description" content="Discover films with MovieLens collaborative filtering and explore the evidence through interactive charts."><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="cinema.css?v=genres-4"></head><body data-page="{slug}"><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html"><span class="brand-icon">▦</span> NEXT FRAME<span class="lab">DISCOVERY LAB</span></a><span class="local-badge">MOVIE DISCOVERY</span></header><nav aria-label="Main navigation">{nav}</nav><main id="main"><p id="loading" role="status">Loading MovieLens data…</p><div id="content" hidden>{body}</div></main><footer><a class="brand" href="index.html">NEXT FRAME</a><p>B.Y.T.E Data Science Task 7 · MovieLens through October 2023</p><a href="about.html">Sources &amp; methodology</a></footer><script type="module" src="dashboard.js?v=genres-4"></script></body></html>''',encoding='utf8')
print('Built seven MovieLens pages.')




